/* parametercatalog.h -- the parameters each shipped ndm_* plugin reads.
 *
 * Built from templates/template.yaml (parametercatalog.inc, generated by
 * src/ndmanager/tools/pipeline_script_defs.py): every parameter of every
 * program block, the ones the template leaves commented out included, with
 * the template's value and its section of the block's help.  The template
 * itself is checked against the scripts (test_template_parameters.py), so
 * this is the list of what a plugin can be given.
 *
 * SPDX-License-Identifier: GPL-3.0-or-later
 */
#ifndef NDMANAGER_PARAMETERCATALOG_H
#define NDMANAGER_PARAMETERCATALOG_H

#include <QList>
#include <QString>

struct ParameterCatalogEntry {
    QString name;
    QString value;        ///< the template's value (for an entry commented out there, an example)
    QString status;       ///< Mandatory / Optional, as in the template
    bool inTemplate = true;  ///< false: only mentioned, commented out, in the template
    QString help;         ///< the parameter's section of the program's help; may be empty
};

namespace ParameterCatalog {
/** The parameters of @p program, in template order; empty for a program the
 *  template does not describe (an external or user-made plugin). */
QList<ParameterCatalogEntry> forProgram(const QString& program);
/** The help for @p name of @p program, or an empty string. */
QString help(const QString& program, const QString& name);
}

#endif
